CC.EXAMPLES = [{"id":"szablon","title":"Szablon projektu","desc":"Minimalny program: LCD, przyciski, podswietlenie.","main":"/* ============================================================\n * Szablon projektu — symulator zestawu Olimex SAM7-EX256\n * Laboratorium systemow wbudowanych\n *\n * Sterowanie w symulatorze:\n *   - joystick: strzalki na klawiaturze (Enter = wcisniecie)\n *   - SW1 / SW2: klawisze 1 i 2 (albo mysza)\n * ============================================================ */\n#include <targets/AT91SAM7.h>\n#include \"PCF8833U8_lcd.h\"\n\n// przyciski\n#define SW_1       PIOB_SODR_P24\n#define SW_2       PIOB_SODR_P25\n// joystick\n#define JOY_UP     PIOA_SODR_P9\n#define JOY_ENTER  PIOA_SODR_P15\n#define JOY_LEFT   PIOA_SODR_P7\n#define JOY_DOWN   PIOA_SODR_P8\n#define JOY_RIGHT  PIOA_SODR_P14\n// inne\n#define LCD_BACKLIGHT  PIOB_SODR_P20\n#define AUDIO_OUT      PIOB_SODR_P19\n\nint main(void)\n{\n    // wlaczenie zegarow kontrolerow PIO\n    PMC_PCER = PMC_PCER_PIOA | PMC_PCER_PIOB;\n\n    // joystick i przyciski jako wejscia\n    PIOA_PER = JOY_UP | JOY_DOWN | JOY_LEFT | JOY_RIGHT | JOY_ENTER;\n    PIOA_ODR = JOY_UP | JOY_DOWN | JOY_LEFT | JOY_RIGHT | JOY_ENTER;\n    PIOB_PER = SW_1 | SW_2 | LCD_BACKLIGHT;\n    PIOB_ODR = SW_1 | SW_2;\n\n    // podswietlenie jako wyjscie, wlaczone\n    PIOB_OER  = LCD_BACKLIGHT;\n    PIOB_SODR = LCD_BACKLIGHT;\n\n    // wyswietlacz\n    InitLCD();\n    LCDSettings();\n    LCDClearScreen();\n\n    LCDPutStr(\"Symulator\", 20, 30, LARGE, BLACK, WHITE);\n    LCDPutStr(\"SAM7-EX256\", 40, 28, LARGE, BLUE, WHITE);\n    LCDPutStr(\"Nacisnij SW1...\", 70, 20, SMALL, BLACK, WHITE);\n\n    while (1)\n    {\n        if ((PIOB_PDSR & SW_1) == 0)   // SW1 wcisniety (stan niski)\n        {\n            LCDSetRect(90, 20, 110, 110, FILL, GREEN);\n            LCDPutStr(\"SW1 OK!\", 96, 40, MEDIUM, BLACK, GREEN);\n        }\n        if ((PIOB_PDSR & SW_2) == 0)   // SW2 kasuje\n        {\n            LCDSetRect(90, 20, 110, 110, FILL, WHITE);\n        }\n    }\n    return 0;\n}\n","extra":null},{"id":"lab6","title":"Lab 6 — podswietlenie i buzzer","desc":"Pierwszy program wg instrukcji: SW1/SW2 steruja PB20 i PB19.","main":"/* ============================================================\n * LABORATORIUM 6 — pierwszy program wbudowany (wg instrukcji)\n * PRZYKLAD POGLADOWY — pokazuje technike, nie jest kompletnym\n * rozwiazaniem zadania zaliczeniowego.\n *\n * Sterowanie podswietleniem LCD (PB20) i buzzerem (PB19).\n *\n *   SW1 — wlacza podswietlenie + krotki sygnal buzzera\n *   SW2 — wylacza podswietlenie + dluzszy sygnal buzzera\n *\n * W symulatorze: SW1/SW2 to klawisze 1 i 2.\n * Stan podswietlenia widac na wyswietlaczu i diodzie BL,\n * buzzer slychac (mozna wyciszyc) i widac na wskazniku.\n * ============================================================ */\n#include <targets/AT91SAM7.h>\n\n#define LCD_BACKLIGHT PIOB_SODR_P20\n#define AUDIO_OUT     PIOB_SODR_P19\n#define SW_1          PIOB_SODR_P24\n#define SW_2          PIOB_SODR_P25\n\nvoid delay(int n) __attribute__ ((section(\".fast\")));\n// prototyp procedury opoznienia, uruchamiaj w RAM-ie\n\nvoid delay(int n)        // procedura opoznienia\n{\n    volatile int i;\n    for (i = 3000 * n; i > 0; i--)\n    {\n        __asm__(\"nop\");\n    }\n}\n\nint main(void)\n{\n    PMC_PCER = PMC_PCER_PIOB;            // wlaczenie urzadzenia we/wy PIOB\n\n    PIOB_OER = LCD_BACKLIGHT | AUDIO_OUT;  // OUTPUT ENABLE\n    PIOB_PER = LCD_BACKLIGHT | AUDIO_OUT;  // PIO ENABLE\n\n    while (1)\n    {\n        if ((PIOB_PDSR & SW_1) == 0)\n        {\n            PIOB_SODR |= LCD_BACKLIGHT;  // ustawienie 1\n            PIOB_SODR |= AUDIO_OUT;\n            delay(1);\n            PIOB_CODR |= AUDIO_OUT;\n            delay(1);\n        }\n        if ((PIOB_PDSR & SW_2) == 0)\n        {\n            PIOB_CODR |= LCD_BACKLIGHT;  // ustawienie 0\n            PIOB_SODR |= AUDIO_OUT;\n            delay(5);\n            PIOB_CODR |= AUDIO_OUT;\n            delay(5);\n        }\n    }\n    return 0;\n}\n","extra":null},{"id":"lab8","title":"Lab 8 — klawiatura i joystick","desc":"Stany joysticka i przyciskow na LCD (zad. 8.1).","main":"/* ============================================================\n * LABORATORIUM 8 — obsluga klawiatury i joysticka (zad. 8.1)\n * PRZYKLAD POGLADOWY — pokazuje technike, nie jest kompletnym\n * rozwiazaniem zadania zaliczeniowego.\n *\n * Wykrywanie stanu przyciskow SW1/SW2 (port B) i joysticka\n * (port A) przez testowanie bitow rejestru PDSR.\n * Stany wyswietlane na LCD wg makiety z instrukcji (rys. 8.1):\n *\n *            UP\n *     LEFT  ENTER  RIGHT\n *           DOWN\n *     SW1          SW2\n * ============================================================ */\n#include <targets/AT91SAM7.h>\n#include \"PCF8833U8_lcd.h\"\n\n#define LCD_BACKLIGHT PIOB_SODR_P20\n#define SW_1          PIOB_SODR_P24\n#define SW_2          PIOB_SODR_P25\n\n#define JOY_UP    PIOA_SODR_P9   // joystick w gore\n#define JOY_ENTER PIOA_SODR_P15  // joystick wcisniety\n#define JOY_LEFT  PIOA_SODR_P7   // joystick w lewo\n#define JOY_DOWN  PIOA_SODR_P8   // joystick w dol\n#define JOY_RIGHT PIOA_SODR_P14  // joystick w prawo\n\n// rysuje etykiete; stan=1 — podswietlona (klawisz wcisniety)\nstatic void label(char *txt, int x, int y, int stan)\n{\n    if (stan)\n        LCDPutStr(txt, x, y, MEDIUM, WHITE, RED);\n    else\n        LCDPutStr(txt, x, y, MEDIUM, BLACK, WHITE);\n}\n\nint main(void)\n{\n    unsigned int a, b;\n    unsigned int pa = 0xFFFFFFFF, pb = 0xFFFFFFFF; // poprzedni stan\n\n    PMC_PCER = PMC_PCER_PIOA | PMC_PCER_PIOB;  // zegary PIOA i PIOB\n\n    // joystick — wejscia na porcie A\n    PIOA_PER = JOY_UP | JOY_DOWN | JOY_LEFT | JOY_RIGHT | JOY_ENTER;\n    PIOA_ODR = JOY_UP | JOY_DOWN | JOY_LEFT | JOY_RIGHT | JOY_ENTER;\n\n    // przyciski — wejscia, podswietlenie — wyjscie\n    PIOB_PER = SW_1 | SW_2 | LCD_BACKLIGHT;\n    PIOB_ODR = SW_1 | SW_2;\n    PIOB_OER = LCD_BACKLIGHT;\n\n    InitLCD();          // inicjalizacja LCD\n    LCDSettings();      // ustawienie LCD\n    LCDClearScreen();   // wyczyszczenie ekranu\n    PIOB_SODR |= LCD_BACKLIGHT;  // podswietlenie = 1\n\n    LCDPutStr(\"LAB 8 - klawiatura\", 4, 10, SMALL, BLUE, WHITE);\n\n    while (1)\n    {\n        a = PIOA_PDSR;\n        b = PIOB_PDSR;\n        if (a == pa && b == pb) continue;  // nic sie nie zmienilo\n        pa = a; pb = b;\n\n        // bit = 0 oznacza klawisz wcisniety\n        label(\"  UP  \",   30, 44, (a & JOY_UP) == 0);\n        label(\"LEFT\",     60,  6, (a & JOY_LEFT) == 0);\n        label(\"ENTER\",    60, 46, (a & JOY_ENTER) == 0);\n        label(\"RIGHT\",    60, 88, (a & JOY_RIGHT) == 0);\n        label(\" DOWN \",   90, 42, (a & JOY_DOWN) == 0);\n        label(\" SW1 \",   115, 12, (b & SW_1) == 0);\n        label(\" SW2 \",   115, 86, (b & SW_2) == 0);\n    }\n    return 0;\n}\n","extra":null},{"id":"lab9","title":"Lab 9 — wyswietlacz graficzny","desc":"Teksty, prostokaty, tekst transparentny, bitmapy, animacja.","main":"/* ============================================================\n * LABORATORIUM 9 — wyswietlacz graficzny Nokia 6610 (GE12)\n * PRZYKLAD POGLADOWY — pokazuje technike, nie jest kompletnym\n * rozwiazaniem zadania zaliczeniowego.\n *\n * czesc 1: imie, nazwisko i grupa + zaslanianie tekstu\n * czesc 2: kontrastowe prostokaty + tekst transparentny\n * czesc 3: grafika z pliku bmp*.h + animacja\n * ============================================================ */\n#include <targets/AT91SAM7.h>\n#include \"PCF8833U8_lcd.h\"\n#include \"bmp132.h\"\n#include \"bmpChoinka.h\"\n\n#define LCD_BACKLIGHT PIOB_SODR_P20\n\nint main(void)\n{\n    PMC_PCER = PMC_PCER_PIOB;\n\n    PIOB_PER = LCD_BACKLIGHT;\n    PIOB_OER = LCD_BACKLIGHT;\n\n    InitLCD();\n    LCDSettings();\n    LCDClearScreen();\n    PIOB_SODR |= LCD_BACKLIGHT;\n\n    // ---- czesc 1: dane studenta + zaslanianie ----\n    int w1 = LCDPutStr2(10, 5, MEDIUM, BLACK, WHITE, \"Jan Kowalski\");\n    int w2 = LCDPutStr2(25, 5, MEDIUM, BLUE,  WHITE, \"Grupa: GL07\");\n    Delaya(25000000);\n\n    LCDClearXY(10, 5, MEDIUM, w1, RED);   // zaslon tekst prostokatem\n    LCDClearXY(25, 5, MEDIUM, w2, RED);\n    Delaya(15000000);\n\n    // ---- czesc 2: prostokaty + tekst transparentny ----\n    LCDSetRect(0, 0,  131, 65,  FILL, BLUE);    // lewa polowa\n    LCDSetRect(0, 66, 131, 131, FILL, YELLOW);  // prawa polowa\n    LCDSetLine(0, 66, 131, 66, BLACK);          // granica\n    LCDPutStr(\"TEST\", 50, 50, LARGE, RED, TRANSPARENT2);\n    Delaya(25000000);\n\n    // ---- czesc 3: bitmapy + animacja ----\n    while (1)\n    {\n        LCDClearScreen();\n        LCDDrawBmp12(bmpChoinka, 116, 121, 5, 8);\n        LCDPutStr(\"Wesolych Swiat!\", 122, 18, SMALL, RED, TRANSPARENT2);\n        Delaya(12000000);\n\n        LCDClearScreen();\n        LCDDrawBmp12(bmpMikolaj, 120, 120, 6, 6);\n        LCDPutStr(\"Wesolych Swiat!\", 122, 18, SMALL, BLUE, TRANSPARENT2);\n        Delaya(12000000);\n\n        LCDClearScreen();\n        LCDDrawBmp12(bmp132, 132, 132, 0, 0);\n        LCDPutStr(\"bmp 132x132\", 4, 30, SMALL, WHITE, TRANSPARENT2);\n        Delaya(12000000);\n    }\n    return 0;\n}\n","extra":null},{"id":"lab10","title":"Lab 10 — menu (przyklad)","desc":"Menu na listach dwukierunkowych, marker, podmenu, programy.","main":"/* LABORATORIUM 10 — menu aplikacji uzytkownika (przyklad POGLADOWY,\n * nie stanowi kompletnego rozwiazania zadania zaliczeniowego).\n * Sterowanie: joystick GORA/DOL — ruch markera; SW2 — wejscie do\n * podmenu / powrot; SW1 — uruchomienie wybranego programu.\n * W symulatorze: strzalki, klawisze 1 (SW1) i 2 (SW2). */\n#include <targets\\AT91SAM7.h>\n#include \"PCF8833U8_lcd.h\"\n\n// przyciski\n#define SW_1       PIOB_SODR_P24\n#define SW_2       PIOB_SODR_P25\n// joystick\n#define JOY_UP     PIOA_SODR_P9\n#define JOY_ENTER  PIOA_SODR_P15\n#define JOY_LEFT   PIOA_SODR_P7\n#define JOY_DOWN   PIOA_SODR_P8\n#define JOY_RIGHT  PIOA_SODR_P14\n\n#define LCD_BACKLIGHT  PIOB_SODR_P20\n\n#define STUDENT_NAME  \"Jan Kowalski\"\n\n// MENU\ntypedef struct menu_struct menu_t;\nstruct menu_struct {\n    const char *name;\n    menu_t *next;\n    menu_t *prev;\n    menu_t *child;                 // poziom niÅ¼ej (podmenu)\n    menu_t *parent;                // poziom wyÅ¼ej\n    void (*menu_function)(void);   // funkcja \"programu\"\n};\n\n// top-level\nstatic menu_t MENU1, MENU2, MENU3;\n// submenu MENU1\nstatic menu_t M1_P1, M1_P2;\n// submenu MENU2\nstatic menu_t M2_P1, M2_P2;\n// submenu MENU3\nstatic menu_t M3_P1, M3_TO_M1;\n\n// wskaznik na pozycje\nstatic menu_t *currentPointer = 0;\n\n// ======================================================\n// funkcje pomocniczne do obslugi przyciskow\n// ======================================================\nstatic inline unsigned char pressedA(unsigned int mask) { return ((PIOA_PDSR & mask) == 0); }\nstatic inline unsigned char pressedB(unsigned int mask) { return ((PIOB_PDSR & mask) == 0); }\n\nstatic void wait_release_A(unsigned int mask) { while (pressedA(mask)) { } Delaya(200000); }\nstatic void wait_release_B(unsigned int mask) { while (pressedB(mask)) { } Delaya(200000); }\n\n// ======================================================\n// FUNKCJE POMOCNICZE DO RYSOWANIA GUI\n// ======================================================\nstatic void draw_frame(void) {\n    LCDSetRect(0, 0, 131, 131, FILL, GREEN);\n    LCDSetRect(4, 4, 127, 127, NOFILL, BLACK);\n    LCDPutStr(\"LSW\", 112, 10, SMALL, BLACK, GREEN);\n}\n\nstatic void draw_button(int x0, int y0, int x1, int y1, const char *txt) {\n    LCDSetRect(x0, y0, x1, y1, FILL, YELLOW);\n    LCDSetRect(x0, y0, x1, y1, NOFILL, BLACK);\n    LCDPutStr((char*)txt, x0 + 6, y0 + 8, SMALL, BLACK, YELLOW);\n}\n\nstatic void draw_marker(int x0, int y0) {\n    LCDSetRect(x0, y0, x0 + 16, y0 + 16, FILL, YELLOW);\n    LCDSetRect(x0, y0, x0 + 16, y0 + 16, NOFILL, BLACK);\n    LCDPutChar('<', x0 + 3, y0 + 6, SMALL, BLACK, YELLOW);\n}\n\n// kasowanie markera (tlo jest zielone)\nstatic void erase_marker(int x0, int y0) {\n    LCDSetRect(x0, y0, x0 + 16, y0 + 16, FILL, GREEN);\n}\n\n// indeks elementu w 2-elementowym submenu (0/1)\nstatic unsigned char submenu_index(menu_t *head, menu_t *cur) {\n    if (!head || !cur) return 0;\n    if (cur == head) return 0;\n    return 1;\n}\n\nstatic unsigned char is_main_level(void) {\n    return (currentPointer && currentPointer->parent == 0);\n}\n\n// ======================================================\n// Rysowanie ekranÃłw (statycznie - bez markera)\n// ======================================================\nstatic void render_main_static(void) {\n    draw_frame();\n\n    LCDPutStr((char*)STUDENT_NAME, 10, 20, MEDIUM, BLACK, GREEN);\n\n    // 3 pozycje -> MENU 1, MENU 2, MENU 3 (wyÅ¼ej)\n    int bx0 = 35, bx1 = 53;\n    int by0 = 10, by1 = 80;\n\n    draw_button(bx0,      by0, bx1,      by1, \"MENU 1\");\n    draw_button(bx0 + 26, by0, bx1 + 26, by1, \"MENU 2\");\n    draw_button(bx0 + 52, by0, bx1 + 52, by1, \"MENU 3\");\n}\n\nstatic void render_submenu_static(menu_t *top) {\n    draw_frame();\n\n    // tytuÅ submenu (rodzic)\n    draw_button(12, 10, 30, 70, top->name);\n\n    // 2 elementy submenu\n    menu_t *head = top->child;\n    draw_button(35, 10, 53, 80, head->name);\n    draw_button(35+26, 10, 52+26, 80, head->next->name);\n}\n\n// Marker: pozycje dla MAIN i SUBMENU \nstatic void marker_pos_main(menu_t *ptr, int *x, int *y) {\n    int idx = 0;\n    if (ptr == &MENU1) idx = 0;\n    else if (ptr == &MENU2) idx = 1;\n    else idx = 2;\n\n\n    const int bx0 = 35;      // x0 pierwszego przycisku\n    const int bx1 = 53;      // x1 pierwszego przycisku\n    const int step = 26;     // odstÄp miÄdzy przyciskami (w osi X)\n    const int markerW = 16;  // szerokoÅÄ markera (16px)\n\n    // srodkowanie markera\n    int btnW = (bx1 - bx0);               \n    int centerOffset = (btnW - markerW) / 2;   // zwykle wyjdzie 1\n\n    *x = bx0 + idx * step + centerOffset;\n    *y = 84; \n}\nstatic void marker_pos_sub(menu_t *ptr, int *x, int *y) {\n    menu_t *top = ptr->parent;\n    menu_t *head = top->child;\n    unsigned char idx = submenu_index(head, ptr);\n\n    *x = (idx == 0) ? 35 : 35+26;\n    *y = 90;\n}\n\n// czy dwa wskaÅºniki sÄ w tym samym \"kontekÅcie UI\":\n// - oba w MAIN, albo\n// - oba w tym samym SUBMENU (ten sam parent)\nstatic unsigned char same_ui_context(menu_t *a, menu_t *b) {\n    if (!a || !b) return 0;\n\n    unsigned char aMain = (a->parent == 0);\n    unsigned char bMain = (b->parent == 0);\n\n    if (aMain != bMain) return 0;\n    if (aMain) return 1;\n    return (a->parent == b->parent);\n}\n\n// ======================================================\n// Render: peÅny lub tylko marker\n// ======================================================\nstatic void ui_render_full(void) {\n    if (is_main_level()) {\n        render_main_static();\n        int x, y;\n        marker_pos_main(currentPointer, &x, &y);\n        draw_marker(x, y);\n    } else {\n        menu_t *top = currentPointer->parent;\n        render_submenu_static(top);\n        int x, y;\n        marker_pos_sub(currentPointer, &x, &y);\n        draw_marker(x, y);\n    }\n}\n\nstatic void ui_update_marker_only(menu_t *oldPtr) {\n    // jak zmieniÅ siÄ poziom/rodzic -> peÅny render\n    if (!same_ui_context(oldPtr, currentPointer)) {\n        ui_render_full();\n        return;\n    }\n\n    int ox, oy, nx, ny;\n\n    if (oldPtr->parent == 0) {\n        marker_pos_main(oldPtr, &ox, &oy);\n        marker_pos_main(currentPointer, &nx, &ny);\n    } else {\n        marker_pos_sub(oldPtr, &ox, &oy);\n        marker_pos_sub(currentPointer, &nx, &ny);\n    }\n\n    if (ox == nx && oy == ny) return;\n\n    erase_marker(ox, oy);\n    draw_marker(nx, ny);\n}\n\n// ======================================================\n// Ekrany programow - wyjÅcie SW1\n// ======================================================\nstatic void program_wait_exit_sw1(void) {\n    while (!pressedB(SW_1)) { }\n    wait_release_B(SW_1);\n}\n\nstatic void program_screen(const char *title, const char *l1, const char *l2) {\n    draw_frame();\n    draw_button(12, 10, 30, 95, title);\n\n    LCDPutStr((char*)l1, 55, 10, MEDIUM, BLACK, GREEN);\n    LCDPutStr((char*)l2, 70, 10, MEDIUM, BLACK, GREEN);\n\n    LCDPutStr(\"SW1 - wyjscie\", 112, 20, SMALL, BLACK, GREEN);\n}\n\nstatic void prog_m1_p1(void) {\n    program_screen(\"MENU1 / P1\", \"Wybrales PROGRAM 1.\", \"Demo: okrag + X.\");\n    LCDSetCircle(70, 70, 18, BLACK);\n    LCDSetLine(55, 55, 85, 85, BLACK);\n    LCDSetLine(55, 85, 85, 55, BLACK);\n    program_wait_exit_sw1();\n}\n\nstatic void prog_m1_p2(void) {\n    program_screen(\"MENU1 / P2\", \"Wybrales PROGRAM 2.\", \"Demo: prostokaty.\");\n    LCDSetRect(50, 35, 100, 115, NOFILL, BLACK);\n    LCDSetRect(55, 40, 95, 110, NOFILL, BLACK);\n    program_wait_exit_sw1();\n}\n\nstatic void prog_m2_p1(void) {\n    program_screen(\"MENU2 / P1\", \"Pomiar/Status (przyklad).\", \"STATUS: OK\");\n    LCDPutStr(\"STATUS: OK\", 90, 20, LARGE, BLACK, GREEN);\n    program_wait_exit_sw1();\n}\n\nstatic void prog_m2_p2(void) {\n    program_screen(\"MENU2 / P2\", \"Komunikat diagnostyczny.\", \"UART: READY\");\n    LCDPutStr(\"UART: READY\", 90, 20, LARGE, BLACK, GREEN);\n    program_wait_exit_sw1();\n}\n\nstatic void prog_m3_p1(void) {\n    program_screen(\"MENU3 / P1\", \"Wybrales PROGRAM 1.\", \"Demo: linie.\");\n    LCDSetLine(40, 20, 40, 120, BLACK);\n    LCDSetLine(92, 20, 92, 120, BLACK);\n    program_wait_exit_sw1();\n}\n\n// ======================================================\n// Inicjalizacja menu (listy dwukierunkowe + parent/child)\n// ======================================================\nstatic void menu_init(void) {\n    // MAIN (circular)\n    MENU1.name = \"MENU 1\";\n    MENU2.name = \"MENU 2\";\n    MENU3.name = \"MENU 3\";\n\n    MENU1.next = &MENU2; MENU1.prev = &MENU3;\n    MENU2.next = &MENU3; MENU2.prev = &MENU1;\n    MENU3.next = &MENU1; MENU3.prev = &MENU2;\n\n    MENU1.parent = 0; MENU2.parent = 0; MENU3.parent = 0;\n    MENU1.menu_function = 0; MENU2.menu_function = 0; MENU3.menu_function = 0;\n\n    // MENU1 submenu (2 elementy circular)\n    M1_P1.name = \"PROGRAM 1\";\n    M1_P2.name = \"PROGRAM 2\";\n\n    M1_P1.next = &M1_P2; M1_P1.prev = &M1_P2;\n    M1_P2.next = &M1_P1; M1_P2.prev = &M1_P1;\n\n    M1_P1.child = 0; M1_P2.child = 0;\n    M1_P1.parent = &MENU1; M1_P2.parent = &MENU1;\n\n    M1_P1.menu_function = prog_m1_p1;\n    M1_P2.menu_function = prog_m1_p2;\n\n    // MENU2 submenu\n    M2_P1.name = \"PROGRAM 1\";\n    M2_P2.name = \"PROGRAM 2\";\n\n    M2_P1.next = &M2_P2; M2_P1.prev = &M2_P2;\n    M2_P2.next = &M2_P1; M2_P2.prev = &M2_P1;\n\n    M2_P1.child = 0; M2_P2.child = 0;\n    M2_P1.parent = &MENU2; M2_P2.parent = &MENU2;\n\n    M2_P1.menu_function = prog_m2_p1;\n    M2_P2.menu_function = prog_m2_p2;\n\n    // MENU3 submenu: PROGRAM1 + MENU1 (skrÃłt)\n    M3_P1.name = \"PROGRAM 1\";\n    M3_TO_M1.name = \"MENU 1\";\n\n    M3_P1.next = &M3_TO_M1; M3_P1.prev = &M3_TO_M1;\n    M3_TO_M1.next = &M3_P1; M3_TO_M1.prev = &M3_P1;\n\n    M3_P1.parent = &MENU3;\n    M3_TO_M1.parent = &MENU3;\n\n    M3_P1.menu_function = prog_m3_p1;\n    M3_P1.child = 0;\n\n    // skrÃłt: wejÅcie do submenu MENU1\n    M3_TO_M1.menu_function = 0;\n    M3_TO_M1.child = &M1_P1;\n\n    // dzieci MAIN\n    MENU1.child = &M1_P1;\n    MENU2.child = &M2_P1;\n    MENU3.child = &M3_P1;\n\n    // start: main menu na MENU1\n    currentPointer = &MENU1;\n}\n\n// ======================================================\n// Inicjalizacja IO\n// ======================================================\nstatic void io_init(void) {\n    PMC_PCER = PMC_PCER_PIOA | PMC_PCER_PIOB;\n\n    // JOY_UP, JOY_DOWN jako wejÅcia\n    PIOA_PER   = JOY_UP | JOY_DOWN;\n    PIOA_ODR   = JOY_UP | JOY_DOWN;\n\n    // SW1, SW2 jako wejÅcia\n    PIOB_PER   = SW_1 | SW_2 | LCD_BACKLIGHT;\n    PIOB_ODR   = SW_1 | SW_2;\n\n    // backlight jako wyjÅcie\n    PIOB_OER   = LCD_BACKLIGHT;\n    PIOB_SODR |= LCD_BACKLIGHT;\n}\n\n// ======================================================\n// Odczyt zdarzen - polling\n// ======================================================\ntypedef enum {\n    EV_NONE = 0,\n    EV_JOY_UP,\n    EV_JOY_DOWN,\n    EV_SW1,\n    EV_SW2\n} event_t;\n\nstatic event_t read_event(void) {\n    if (pressedA(JOY_UP)) {\n        Delaya(150000);\n        wait_release_A(JOY_UP);\n        return EV_JOY_UP;\n    }\n    if (pressedA(JOY_DOWN)) {\n        Delaya(150000);\n        wait_release_A(JOY_DOWN);\n        return EV_JOY_DOWN;\n    }\n    if (pressedB(SW_1)) {\n        Delaya(150000);\n        wait_release_B(SW_1);\n        return EV_SW1;\n    }\n    if (pressedB(SW_2)) {\n        Delaya(150000);\n        wait_release_B(SW_2);\n        return EV_SW2;\n    }\n    return EV_NONE;\n}\n\n// ======================================================\n// Logika sterowania\n// ======================================================\nstatic menu_t *mainReturnOverride = 0;\nstatic void handle_sw2(void) {\n    if (is_main_level()) {\n        // MAIN: SW2 -> schodzimy do child\n        if (currentPointer->child)\n            currentPointer = currentPointer->child;\n    } else {\n        // SUBMENU: SW2 -> wraca do MAIN\n        // wyjÄtek: jeÅli jesteÅmy na skrÃłcie MENU3->MENU1, wrÃłÄ do MENU1 (a nie do MENU3)\n        if (currentPointer == &M3_TO_M1) {\n            mainReturnOverride = &MENU1;\n        }\n\n        if (mainReturnOverride) {\n            currentPointer = mainReturnOverride;  // marker w MAIN bÄdzie na MENU1\n            mainReturnOverride = 0;               // skasuj override po uÅ¼yciu\n        } else {\n            currentPointer = currentPointer->parent;\n        }\n    }\n}\n\n\nstatic void handle_sw1(void) {\n    // SW1 w MAIN jest ignorowane\n    if (is_main_level()) {\n        return;\n    }\n\n    // w podmenu SW1 uruchamia program albo wchodzi w child (MENU3->MENU1)\n    if (currentPointer->menu_function) {\n        currentPointer->menu_function();\n    } else if (currentPointer->child) {\n        currentPointer = currentPointer->child;\n    }\n}\n\n// ======================================================\n// main\n// ======================================================\nint main(void) {\n    io_init();\n\n    InitLCD();\n    LCDClearScreen();\n\n    menu_init();\n    ui_render_full();\n\n    while (1) {\n        event_t ev = read_event();\n        if (ev == EV_NONE) continue;\n\n        menu_t *old = currentPointer;\n\n        // poruszanie sie po aktualnym poziomie TYLOK MARKEREM\n        if (ev == EV_JOY_UP) {\n            currentPointer = currentPointer->prev;\n            ui_update_marker_only(old);\n        }\n        else if (ev == EV_JOY_DOWN) {\n            currentPointer = currentPointer->next;\n            ui_update_marker_only(old);\n        }\n        else if (ev == EV_SW2) {\n            handle_sw2();\n            ui_render_full();   // zmiana poziomu -> peÅny render\n        }\n        else if (ev == EV_SW1) {\n            handle_sw1();\n\n            // po programie UI byÅo nadpisane -> odtwÃłrz peÅny ekran\n            if (!is_main_level()) {\n                ui_render_full();\n            }\n        }\n    }\n\n    return 0;\n}\n","extra":null},{"id":"lab11","title":"Lab 11 / LSW6 — timery PIT i TC0","desc":"Odmierzanie czasu timerami, miganie podswietleniem co 1 s.","main":"/* ============================================================\n * LABORATORIUM — timery: PIT oraz Timer Counter 0 (TC0)\n * (instrukcja LSW6 / projekt lab11)\n * PRZYKLAD POGLADOWY — pokazuje technike, nie jest kompletnym\n * rozwiazaniem zadania zaliczeniowego.\n *\n * Wybierz wariant zmieniajac ponizsze #define:\n *   WARIANT 1 — PIT:  miganie podswietleniem co ~1 s\n *               (PIV=299999 -> 0,1 s; 10 przepelnien = 1 s)\n *   WARIANT 2 — TC0:  RC compare, MCK/128, RC=37499 -> 0,1 s;\n *               zmiana stanu PB20 co 10 okresow (~1 s)\n * ============================================================ */\n#include <targets/AT91SAM7.h>\n#include \"PCF8833U8_lcd.h\"\n\n#define WARIANT 2\n\n#define LCD_BACKLIGHT PIOB_SODR_P20\n\nint main(void)\n{\n    InitLCD();\n    LCDClearScreen();\n    LCDPutStr(\"Timery: PIT / TC0\", 10, 10, SMALL, BLACK, WHITE);\n    LCDPutStr(\"miganie BL co 1s\", 25, 10, SMALL, BLUE, WHITE);\n\n#if WARIANT == 1\n    /* ---------------- PIT ---------------- */\n    PMC_PCER = PMC_PCER_PIOB;          // zegar PIOB\n    PIOB_PER = LCD_BACKLIGHT;\n    PIOB_OER = LCD_BACKLIGHT;\n\n    PIT_MR = 299999 | (1 << 24);       // PIV oraz bit PITEN\n    PIT_PIVR;                          // pusty odczyt — zerowanie licznikow\n\n    while (1)\n    {\n        if ((PIT_SR & (1 << 0)) != 0)  // flaga PITS ustawiona?\n        {\n            int liczniki = PIT_PIIR;   // odczyt bez kasowania\n            int picnt = liczniki >> 20;  // liczba przepelnien CPIV\n            if (picnt >= 10)           // 10 x 0,1 s = 1 s\n            {\n                if ((PIOB_PDSR & (1 << 20)) != 0)\n                    PIOB_CODR = (1 << 20);\n                else\n                    PIOB_SODR = (1 << 20);\n                PIT_PIVR;              // kasuje PICNT i flage PITS\n            }\n        }\n    }\n#else\n    /* ---------------- TC0 ---------------- */\n    PMC_PCER = PMC_PCER_PIOB | (1 << 12);  // zegar PIOB oraz TC0 (PID=12)\n    PIOB_PER = LCD_BACKLIGHT;\n    PIOB_OER = LCD_BACKLIGHT;\n\n    int licznik = 0;\n\n    TC0_CCR = (1 << 1);                // CLKDIS — wylacz licznik na czas konfiguracji\n    TC0_SR;                            // pusty odczyt — reset flag\n    TC0_CMR = (1 << 14) | 3;           // CPCTRG (bit14) + preskaler MCK/128 (TCCLKS=3)\n    TC0_RC  = 37499;                   // 48 MHz / 128 * 0,1 s = 37500 -> RC=37499\n    TC0_CCR = (1 << 2) | (1 << 0);     // SWTRG + CLKEN — start\n\n    while (1)\n    {\n        if ((TC0_SR & (1 << 4)) != 0)  // flaga CPCS (odczyt SR ja kasuje)\n        {\n            licznik++;\n            if (licznik >= 10)         // 10 x 0,1 s = 1 s\n            {\n                if ((PIOB_PDSR & (1 << 20)) != 0)\n                    PIOB_CODR = (1 << 20);\n                else\n                    PIOB_SODR = (1 << 20);\n                licznik = 0;\n            }\n        }\n    }\n#endif\n    return 0;\n}\n","extra":null}];
